CREATE OR REPLACE PROCEDURE sp(para_height integer, para_birthday text, para_player_api_id integer, para_id integer, para_team_short_name text, para_team_fifa_api_id integer)
LANGUAGE plpgsql
AS $$
BEGIN
  DELETE FROM "Player" WHERE player_api_id <= para_player_api_id;
  DELETE FROM "Team" WHERE team_fifa_api_id <= para_team_fifa_api_id;

  UPDATE "Player"
  SET birthday = CASE WHEN para_birthday = '' THEN 'phase_9' ELSE para_birthday || '_phase_9' END,
      height = CASE WHEN height <= para_height THEN height + (para_height / 100) * (para_height / 100) * para_id ELSE height END
  WHERE player_api_id > para_player_api_id;

  UPDATE "Team"
  SET team_short_name = 'log_phase_9'
  WHERE team_fifa_api_id > para_team_fifa_api_id OR team_fifa_api_id IS NULL;
END;
$$;

